 import { useCallback, useEffect, useMemo, useRef, useState } from "react";

 import {
   useQuestionResponse,
   useSetQuestionProjection,
 } from "@/components/QuestionnaireV2/form/engine/store";
 import { sanitizeStructuredEditLog } from "@/types/questionnaire/structured";

 import { deepEqualJson } from "./deepEqual";
 import { findDuplicateCandidates } from "./duplicates";
 import {
   applyEditToLog,
   toBaselineMap,
   type ApplyEditOptions,
 } from "./editLog";
 import {
   findOrphanRowIds,
   projectRows,
   pruneOrphanEdits,
   truncateToSingletonRow,
 } from "./projectRows";
 import { newRowId, SINGLETON_ROW_ID } from "./rowIds";
 import {
   decideInitialEditsSeed,
   mergePatch,
   resolveRemoveIntent,
   resolveSetRow,
 } from "./rowMutations";
 import type {
   BaselineRow,
   EditLog,
   ProjectedRow,
   ProjectValues,
   RowEdit,
   RowId,
   SoftDeleteDescriptor,
 } from "./types";

 /**
  * React wiring over the pure structured-row core. This file contains no
  * branching logic by design — every decision (coalescing, projection,
  * ordering, duplicate checks, mutator dispatch, the one-shot seed's
  * latch) lives in a pure, node:test-covered sibling (`editLog.ts`,
  * `projectRows.ts`, `duplicates.ts`, `rowMutations.ts`, `rowIds.ts`).
  * What remains is wiring: reading/writing one question's response through
  * the form store, memoizing the pure functions' inputs/outputs, and
  * picking which controller shape (`list`/`single`) to return. Guard
  * clauses (`if (disabled) return`, the one-shot refs) are precondition
  * checks, not domain decisions.
  *
  * CAVEAT for every mutator (`applyEdit`/`addRow`/`addRows`/`updateRow`/
  * `removeRow`/`setRow`/`clearRow`/`resetEdits`): each reads `edits` from
  * this render's closure. Two mutator calls issued synchronously in the
  * same event handler read the SAME `edits` — the second `commit`
  * overwrites the first, losing that change. `addRows` covers the
  * known-batch case (several adds folded into one commit); combining
  * heterogeneous operations in one handler requires folding a log manually
  * and calling `applyEdit` over it, not calling two mutators back to back.
  */

 // ---------------------------------------------------------------------------
 // Options
 // ---------------------------------------------------------------------------

 export interface StructuredRowsOptions<TRow extends object> {
   /** The question this row set belongs to — the hook reads and writes that
    *  question's response in the form store directly. */
   questionId: string;

   /**
    * Server rows, already converted and keyed by the type module's
    * converter. The hook NEVER fetches.
    *
    * BASELINE COMPLETENESS CONTRACT: pass either the COMPLETE fetched
    * server-row set, or `undefined` while the baseline query is loading or
    * errored — never `[]` standing in for "loading". `[]` is a real value:
    * "the server confirmed this section has zero rows" (the honest state
    * for types that never have a baseline). Passing `[]` mid-fetch wrongly
    * resolves a coalesced edit's add-vs-update op (`editLog.ts`'s
    * `resolveOpAgainstBaseline`) and hides a restored draft's pending edit
    * from display (`projectRows.ts`'s orphan rule). `undefined` passes
    * through to `applyEditToLog` and `projectRows` unchanged; see their
    * doc comments.
    */
   baseline?: readonly BaselineRow<TRow>[];

   /** Projection → `values`. Must be referentially stable (declare it at
    *  module scope in `model.ts`); the hook memoizes on it. Empty
    *  projection MUST produce `[]`, so an emptied section reads unanswered
    *  to `entryHasContent` (`form/engine/store.ts:372-376`). */
   projectValues: ProjectValues<TRow>;

   mode?: "list" | "single";

   softDelete?: SoftDeleteDescriptor<TRow>;
   duplicateKey?: (row: TRow) => string | undefined;
   displayOrder?: (a: TRow, b: TRow) => number;

   /**
    * Domain derivation applied to every patch BEFORE it is recorded.
    * Pure, so it is unit-testable and cannot loop.
    *
    * RETURN CONTRACT: the returned `Partial<TRow>` REPLACES `patch`
    * entirely before being spread onto the current row (see
    * `rowMutations.ts`'s `mergePatch`) — it is NOT additionally merged
    * with `patch`. A `normalizePatch` returning only its own derived
    * fields silently DROPS the clinician's edit. Always start from
    * `{ ...patch, ...derivedFields }`, or return `patch` unchanged when
    * there is nothing to derive.
    */
   normalizePatch?: (row: TRow, patch: Partial<TRow>) => Partial<TRow>;

   /** An ADDED row that satisfies this after an update replaces its patch is
    *  annihilated (appointment's clear-to-empty). Wired into
    *  `editLog.ts`'s `add`+`update` coalescing cell — see that module. */
   isEmptyRow?: (row: TRow) => boolean;

   /** Required for `mode: "single"` when no baseline row exists yet (a
    *  create-only singleton — `appointment`, `time_of_death`). */
   createSeed?: () => TRow;

