   { ok: true; rowId: RowId } | { ok: false; reason: "duplicate" | "disabled" };

 export interface ListRowsController<
   TRow extends object,
 > extends StructuredRowsBase<TRow> {
   rows: readonly ProjectedRow<TRow>[];
