7. ## CARE Type Organization Structure
8. - emr/: Electronic Medical Records (patient/, tagConfig/, etc.)
9. - facility/: Hospital/clinic facility management types
10. - auth/: Authentication and authorization types
11. - user/: User roles (doctor, nurse, admin) and permissions
12. - billing/: Healthcare billing and insurance types
13. - inventory/: Medical equipment and supplies
14. - scheduling/: Appointments, shifts, medical procedures
15. 
16. ## Healthcare Domain Enums
17. ```typescript
18. // Follow existing enum patterns from patient.ts
19. export enum BloodGroupChoices {
20.   A_negative = "A_negative",
21.   A_positive = "A_positive", 
22.   B_negative = "B_negative",
23.   B_positive = "B_positive",
24.   AB_negative = "AB_negative",
25.   AB_positive = "AB_positive", 
26.   O_negative = "O_negative",
27.   O_positive = "O_positive",
28.   Unknown = "unknown",
29. }
30. ```
31. 
32. ## Medical Interface Patterns
33. ```typescript
34. // EMR-specific interface patterns
35. export interface PatientRead {
36.   id: string;
37.   name: string;
38.   blood_group?: BloodGroupChoices;
39.   instance_tags: TagConfig[];
40.   geo_organization: Organization;
41.   instance_identifiers: PatientIdentifier[];
42.   created_by: UserReadMinimal | null;
43.   year_of_birth: number;
44.   // Always include medical-specific fields
45. }
46. ```
47. 
48. ## Import Path Conventions for Types
49. - Cross-domain imports: `import { TagConfig } from "@/types/emr/tagConfig/tagConfig"`
50. - Organization imports: `import { Organization } from "@/types/organization/organization"`
51. - User imports: `import { UserReadMinimal } from "@/types/user/user"`
52. - Patient identifiers: `import { PatientIdentifier } from "@/types/patient/patientIdentifierConfig/patientIdentifierConfig"`
53. - EMR patient types: `import { PatientRead, PatientCreate } from "@/types/emr/patient/patient"`
54. - Facility types: `import { FacilityRead, FacilityCreate } from "@/types/facility/facility"`
55. 
56. ## Healthcare Data Validation Types
57. - Medical records: Strict validation for patient safety (blood type, allergies, medications)
58. - Dosage validation: Numeric types with units (mg, ml, etc.)
59. - Date/time validation: Medical appointments, medication schedules, shift timings
60. - Identifier validation: Patient ID, facility ID, insurance numbers
61. 
62. ## API Response Type Patterns
63. ```typescript
64. // Paginated medical records
65. export interface PatientListResponse {
66.   count: number;
67.   next: string | null;
68.   previous: string | null;
69.   results: PatientRead[];
70. }
71. 
72. // Medical procedure responses  
73. export interface EncounterRead {
74.   id: string;
75.   patient: PatientRead;
76.   facility: { id: string; name: string; };
77.   status: EncounterStatus;
78.   created_date: string; // ISO 8601
79.   care_team: CareTeamResponse[];
80. }
81. ```
82. 
83. ## Medical Form Type Patterns
84. ```typescript
85. // Patient admission form
86. export interface PatientAdmissionForm {
87.   personalInfo: {
88.     name: string;
89.     age: number;
90.     blood_group: BloodGroupChoices;
91.     emergency_phone_number: string;
92.   };
93.   medicalHistory: {
94.     allergies: string[];
95.     currentMedications: MedicationRead[];
96.     previousSurgeries: string[];
97.   };
98.   insuranceInfo?: {
99.     provider: string;
100.     policyNumber: string;
101.   };
102. }
103. ```
104. 
105. ## Role-Based Access Types
106. ```typescript
107. // User permissions for healthcare roles
108. export interface CurrentUserRead extends UserRead, Permissions {
109.   user_type: UserType;
110.   facilities: FacilityBareMinimum[];
111.   home_facility: FacilityBareMinimum;
112. }
113. 
114. export type UserType = 'doctor' | 'nurse' | 'staff' | 'volunteer' | 'administrator';
115. ```
116. 
117. ## Medical Measurement Types
118. ```typescript
119. // Vital signs with proper units
120. export interface VitalSigns {
121.   temperature: { value: number; unit: 'celsius' | 'fahrenheit' };
122.   bloodPressure: { systolic: number; diastolic: number; unit: 'mmHg' };
123.   heartRate: { value: number; unit: 'bpm' };
124.   oxygenSaturation: { value: number; unit: 'percentage' };
125.   recordedAt: string; // ISO 8601
126.   recordedBy: UserReadMinimal;
127. }
128. ```
129. 
130. ## Healthcare-Specific Utility Types
131. ```typescript
132. // Emergency priority levels
133. export type EmergencyPriority = 'critical' | 'urgent' | 'semi-urgent' | 'non-urgent';
134. 
135. // Bed status in facility
136. export type BedStatus = 'occupied' | 'available' | 'maintenance' | 'reserved';
137. 
138. // Medication administration routes
139. export type MedicationRoute = 'oral' | 'intravenous' | 'intramuscular' | 'topical' | 'inhaled';
140. ```
141. 
142. ## Zod Schema Integration
143. ```typescript
144. import { z } from 'zod';
145. 
146. // Zod schema matching TypeScript interface
147. export const PatientAdmissionSchema = z.object({
148.   name: z.string().min(2).max(100),
149.   age: z.number().min(0).max(150),
150.   bloodGroup: z.nativeEnum(BloodGroupChoices),
151.   emergencyContact: z.string().regex(/^\+?[\d\s-()]+$/), // Phone validation
152. });
153. 
154. export type PatientAdmissionFormData = z.infer<typeof PatientAdmissionSchema>;
155. ```
156. 
157. ## Medical Data Privacy Types
158. ```typescript
159. // PHI (Protected Health Information) markers
160. export interface PHISafePatientData {
161.   id: string; // Hashed/anonymized
162.   ageRange: '0-10' | '11-20' | '21-30' | '31-40' | '41-50' | '51+';
163.   condition: string;
164.   // Never include name, address, phone in PHI-safe types
165. }
166. ```
167. 
168. ## Integration with React Query
169. ```typescript
170. // API query result types
171. export type PatientQueryResult = {
172.   data: PatientRead;
173.   isLoading: boolean;
174.   error: ApiError | null;
175.   refetch: () => void;
176. };
177. ```

