1. import { Trash2 } from "lucide-react";
2. import { createPortal } from "react-dom";
3. import { useTranslation } from "react-i18next";
4. 
5. import { cn } from "@/lib/utils";
6. 
7. import { Button } from "@/components/ui/button";
8. 
9. import { QuestionnaireFormProvider } from "@/components/QuestionnaireV2/form/FormContext";
10. 
11. import type { RendererSubject } from "@/components/QuestionnaireV2/form/types";
12. 
13. import { FillCanvas } from "./FillCanvas";
14. import { FillOutline } from "./FillOutline";
15. import { FillOutlineRail } from "./FillOutlineRail";
16. import type { FormStore } from "./StoreRegistrar";
17. import { StoreRegistrar } from "./StoreRegistrar";
18. import type { FillFormEntry } from "./formSession";
19. 
20. /**
21.  * One questionnaire of the session: its own provider (one store), its
22.  * canvas block in the shared scroll, and its outline pieces PORTALED
23.  * into the overlay's shared hosts (panel rows + rail ticks) — they must
24.  * live inside this provider to read this form's store.
25.  */
26. export function FillFormSection({
27.   form,
28.   subject,
29.   outlineHost,
30.   railHost,
31.   outlineLabel,
32.   onStore,
33.   onRemove,
34.   frozen = false,
35. }: {
36.   form: FillFormEntry;
37.   subject: RendererSubject;
38.   outlineHost: HTMLElement | null;
39.   railHost: HTMLElement | null;
40.   /** Accessible name for this form's outline landmark. The host passes
41.    *  the questionnaire title once a session holds more than one form, so
42.    *  the stacked navs stay distinguishable. */
43.   outlineLabel?: string;
44.   onStore: (key: string, store: FormStore | null) => void;
45.   onRemove?: (key: string) => void;
46.   /** The session is mid-submit — forwarded into this form's renderer
47.    *  context (freezes every question) and disables the Remove affordance
48.    *  below, so a click during flight can't drop a form the in-flight
49.    *  batch already accounts for. */
50.   frozen?: boolean;
51. }) {
52.   const { t } = useTranslation();
53.   return (
54.     <QuestionnaireFormProvider
55.       questionnaire={form.questionnaire}
56.       mode="fill"
57.       subject={subject}
58.       initialResponses={form.initialResponses}
59.       frozen={frozen}
60.     >
61.       <StoreRegistrar formKey={form.key} onStore={onStore} />
62.       {outlineHost &&
63.         createPortal(
64.           <div className="flex flex-col gap-3">
65.             <p className="truncate pl-2 text-base font-semibold text-gray-950">
66.               {form.questionnaire.title}
67.             </p>
68.             <FillOutline ariaLabel={outlineLabel} />
69.           </div>,
70.           outlineHost,
71.         )}
72.       {railHost && createPortal(<FillOutlineRail />, railHost)}
73.       {/* The divider keys off `isPrimary`, not `:first-child` — the
74.           restore bar and the error panel share this scroll, so DOM
75.           position is not a reliable "first form" signal. */}
76.       <section
77.         data-form-key={form.key}
78.         className={cn(!form.isPrimary && "border-t border-gray-200 pt-6")}
79.       >
80.         {/* The canvas header already names the questionnaire — legacy
81.             parity here is only the drop affordance, and only the added
82.             forms get one. */}
83.         {onRemove && !form.isPrimary && (
84.           <div className="mx-auto mb-2 flex w-full max-w-3xl justify-end">
