38. export type StructuredSlotStateKind =
39.   "ready" | "unknown_type" | "subject_mismatch" | "missing_context";
40. 
41. export interface StructuredQuestionSummary {
42.   /** The structured type name — a core type (`"allergy_intolerance"`) or
43.    *  a namespaced plugin id (`"acme.assessment"`). */
44.   type: string;
45.   /** Absent when the type could not be resolved at all
46.    *  (`slotState: "unknown_type"`). */
47.   contract?: 2;
48.   /** Mirrors `resolveStructuredSlotState`'s discriminant — "ready" here
49.    *  means the same thing it means on screen (`StructuredSlot`). */
50.   slotState: StructuredSlotStateKind;
51.   /** The type's own published row schema. `undefined` when the type has
52.    *  not published one, in which case `applyStructuredEdit` rejects
53.    *  every write to it, fail-closed. */
54.   rowSchema?: z.ZodType;
