128.   if (entry.value === undefined) return null;
129.   if (entry.value instanceof Date) {
130.     return entry.type === "date"
131.       ? formatLocalDate(entry.value)
132.       : entry.value.toISOString();
133.   }
134.   if (typeof entry.value === "object") return null; // defensive; never hit for a plain question
135.   return entry.value;
136. }
137. 
138. function summarizePlainValue(
139.   response: QuestionnaireResponse | undefined,
140. ): PlainValueSummary {
