146.  *  same way `StructuredSlot` does, so "ready" here means the same thing
147.  *  it means on screen. */
148. function structuredSummary(
149.   question: Question,
150.   form: FillFormEntry,
151.   subjectContext: Partial<
152.     Record<"patientId" | "encounterId" | "facilityId", string>
153.   >,
154.   response: QuestionnaireResponse | undefined,
155. ): StructuredQuestionSummary {
156.   const type = question.structured_type as string;
157.   const slotState = resolveStructuredSlotState(
158.     type,
159.     form.questionnaire.subject_type,
160.     subjectContext,
161.   );
162.   const definition =
163.     slotState.kind === "unknown_type" ? undefined : slotState.definition;
164.   return {
165.     type,
166.     contract: definition?.contract,
167.     slotState: slotState.kind,
