263. /** The gates shared by both write paths (`setValue`,
264.  *  `applyStructuredEdit`): the question must exist in the resolved form,
265.  *  not be read-only, have a live store entry and a response slot, and be
266.  *  enabled — itself and every ancestor — since `composeBatch` would never
267.  *  submit a disabled question's answer. */
268. function resolveWritableQuestion(
269.   snapshot: SessionSnapshot,
270.   formKey: string | undefined,
271.   questionId: string,
272. ): AssistantResult<WritableQuestion> {
273.   const form = resolveForm(formKey, snapshot.forms);
274.   if (!form) return fail(formNotFoundError(formKey));
275.   const path = findQuestionPath(form.questionnaire.questions, questionId);
276.   if (!path) return fail(noSuchQuestionError(questionId, form));
277.   const question = path[path.length - 1];
278. 
279.   if (question.read_only) {
280.     return fail(`Question "${questionId}" is read-only`);
281.   }
282.   const store = snapshot.getStore(form.key);
283.   if (!store)
284.     return fail(`Form "${form.questionnaire.title}" is not ready yet`);
285.   const previous = store.get(responsesAtom);
286.   const response = previous[question.id];
287.   if (!response) {
288.     return fail(
289.       `Question "${questionId}" is not part of the open form any more`,
290.     );
291.   }
292.   const linkIndex = buildLinkIndex(form.questionnaire.questions);
293.   if (!isPathEnabled(path, previous, linkIndex)) {
294.     return fail(
295.       `Question "${questionId}" is currently disabled by its enable_when conditions and would not be submitted; answer the question it depends on first`,
296.     );
297.   }
298.   return { ok: true, value: { question, store, previous, response } };
299. }
300. 
301. function setValueImpl(
302.   snapshot: SessionSnapshot,
303.   formKey: string | undefined,
304.   questionId: string,
305.   values: PlainValueEntry[],
306.   note: string | undefined,
307. ): AssistantResult {
308.   const resolved = resolveWritableQuestion(snapshot, formKey, questionId);
309.   if (!resolved.ok) return resolved;
310.   const { question, store, previous, response: current } = resolved.value;
311. 
312.   if (
313.     question.type === "group" ||
314.     question.type === "display" ||
315.     question.type === "structured" ||
316.     question.structured_type
317.   ) {
318.     return fail(
319.       `Question "${questionId}" is a ${question.type} question and cannot be answered with plain values`,
320.     );
321.   }
322.   if (values.length > 1 && !question.repeats) {
323.     return fail(`Question "${questionId}" takes a single value`);
324.   }
325.   const rawValues = values as RawAnswerValue[];
326.   const bounds = checkSetValueBounds(rawValues, note);
327.   if (!bounds.ok) return fail(bounds.error ?? "Invalid input");
328. 
329.   const coerced: ResponseValue[] = [];
330.   for (const raw of rawValues) {
331.     const result = coercePlainResponseValue(question, raw);
332.     if (!result.ok) return fail(result.error);
333.     coerced.push(result.value);
334.   }
335. 
336.   store.set(responsesAtom, {
337.     ...previous,
338.     [question.id]: {
339.       ...current,
340.       values: coerced,
341.       ...(note !== undefined && { note }),
342.     },
343.   });
344.   clearQuestionErrorsInState(store.get, store.set, question.id);
345.   return ok();
346. }
347. 
348. function applyStructuredEditImpl(
349.   snapshot: SessionSnapshot,
350.   formKey: string | undefined,
351.   questionId: string,
352.   edit: ApplyStructuredEditInput,
353. ): AssistantResult<{ rowId: string }> {
354.   const resolved = resolveWritableQuestion(snapshot, formKey, questionId);
355.   if (!resolved.ok) return resolved;
356.   const { question, store, previous, response } = resolved.value;
357. 
358.   if (question.type !== "structured" || !question.structured_type) {
359.     return fail(`Question "${questionId}" is not a structured question`);
360.   }
361. 
362.   const definition = resolveStructuredType(question.structured_type);
363.   if (!definition) {
364.     return fail(`Unknown structured type "${question.structured_type}"`);
365.   }
366.   if (definition.contract !== 2) {
367.     // `contract` is typed as the literal 2, but a runtime-registered
368.     // (module-federated) plugin definition is untyped JS at this boundary
369.     // — reject anything that doesn't declare the current contract rather
370.     // than appending to an edit log the type may not maintain.
371.     return fail(
372.       `Structured type "${question.structured_type}" is on the legacy contract and does not accept assistant edits yet`,
373.     );
374.   }
375. 
376.   if ((edit.op === "update" || edit.op === "remove") && !edit.rowId) {
377.     return fail(`rowId is required for op "${edit.op}"`);
378.   }
379.   const rowId = edit.rowId ?? crypto.randomUUID();
380. 
381.   const validated = validateStructuredPatch(
382.     rowSchemaOf(definition),
383.     edit.patch,
384.   );
385.   if (!validated.ok) return fail(validated.error);
386. 
387.   // Same edit-log path a human tap takes: `applyEditToLog` is the exact
388.   // function every `useStructuredRows` mutator calls. No `baseline` is
389.   // supplied — this handle lives at the session level, above any single
390.   // question's mounted editor, so it cannot see that question's fetched
391.   // server rows. Without a baseline, `applyEditToLog` resolves a
392.   // resurrection/re-add conservatively to "update" rather than risking a
393.   // duplicate-create "add" — see `resolveOpAgainstBaseline`.
394.   const currentLog = (response.edits ?? []) as EditLog<Record<string, unknown>>;
395.   const nextEdit: RowEdit<Record<string, unknown>> = {
396.     rowId,
397.     op: edit.op,
398.     patch: validated.value as Record<string, unknown>,
399.   };
400.   const nextLog = applyEditToLog(currentLog, nextEdit, {});
401. 
402.   // Projection without a baseline renders every add/update patch's own
403.   // content (`projectRows`' "baseline not yet known" behavior). It does
404.   // NOT apply the type's own `isEmptyRow` filter — that predicate lives
405.   // in each type's `model.ts`, out of this generic handle's reach — so an
406.   // all-empty row can appear in the display projection (display-only:
407.   // submit derives from `edits`, not from this mirror).
408.   const projectedRows = projectRows(undefined, nextLog, {}).map(
409.     (entry) => entry.row,
410.   );
411.   const nextValues = projectionResponseValues(
412.     question.structured_type,
413.     projectedRows,
414.   );
415. 
416.   store.set(responsesAtom, {
417.     ...previous,
418.     [question.id]: {
419.       ...response,
420.       values: nextValues,
421.       edits: nextLog as StructuredEditRecord[],
422.     },
423.   });
424.   clearQuestionErrorsInState(store.get, store.set, question.id);
425.   return { ok: true, value: { rowId } };
426. }
427. 
428. function createHandle(
429.   latestRef: RefObject<SessionSnapshot>,
430.   listeners: Set<() => void>,
431. ): FillAssistantHandle {
432.   return {
433.     listForms: () => listFormsImpl(latestRef.current.forms),
434.     listQuestions: (formKey) => {
435.       const form = resolveForm(formKey, latestRef.current.forms);
436.       if (!form) return [];
437.       const { patientId, encounterId, facilityId } = rendererSubjectOf(
438.         latestRef.current.subject,
439.       );
440.       return buildQuestionDescriptors(
441.         form,
442.         { patientId, encounterId, facilityId },
443.         latestRef.current.getStore,
444.       );
445.     },
446.     getValue: (formKey, questionId) =>
447.       getValueImpl(latestRef.current, formKey, questionId),
448.     setValue: (formKey, questionId, values, note) =>
449.       setValueImpl(latestRef.current, formKey, questionId, values, note),
450.     applyStructuredEdit: (formKey, questionId, edit) =>
451.       applyStructuredEditImpl(latestRef.current, formKey, questionId, edit),
452.     subscribe: (listener) => {
453.       listeners.add(listener);
454.       return () => {
455.         listeners.delete(listener);
456.       };
457.     },
458.   };
459. }
460. 
461. export interface UseFillAssistantSessionArgs {
462.   subject: FillSubject;
463.   forms: FillFormEntry[];
464.   getStore: GetStore;
465.   /** Bumped whenever `StoreRegistrar` registers or unregisters a form's
466.    *  jotai store — read only to retrigger the subscription effect below;
467.    *  `getStore` itself is a stable `useCallback` reading through a ref
468.    *  (`QuestionnaireFillPage.tsx`'s `storesRef`), so its identity never
469.    *  changes on its own. */
470.   storesVersion: number;
471. }
472. 
473. /**
474.  * Builds this fill session's assistant handle. Session-scoped: the handle
475.  * object is created once (a `useRef`) and its methods always read the
476.  * LATEST `forms`/`getStore`/`subject` through a mutable ref updated every
477.  * render — never a stale closure, and never a module-global lookup.
478.  *
479.  * Also wires the internal change-notification fan-out `subscribe()`
480.  * exposes: one effect subscribes to every currently mounted form's
481.  * `responsesAtom` (re-subscribing whenever `forms`/`storesVersion`
482.  * change, so a form added or removed mid-session is picked up), and fans
483.  * every fire out to whatever listeners `subscribe()` has collected. A
484.  * human edit, an assistant write, and a baseline-refresh projection
485.  * update all go through the same atom, so all three notify identically.
486.  */
487. export function useFillAssistantSession({
488.   subject,
489.   forms,
490.   getStore,
491.   storesVersion,
492. }: UseFillAssistantSessionArgs): FillAssistantHandle {
493.   const latestRef = useRef<SessionSnapshot>({ subject, forms, getStore });
494.   latestRef.current = { subject, forms, getStore };
495. 
496.   // The `subscribe()` fan-out list — one Set per hook instance (per
497.   // mounted session), never shared across mounts.
498.   const listenersRef = useRef<Set<() => void>>(new Set());
499. 
500.   const handleRef = useRef<FillAssistantHandle | undefined>(undefined);
501.   if (!handleRef.current) {
502.     handleRef.current = createHandle(latestRef, listenersRef.current);
503.   }
504. 
505.   const notify = useCallback(() => {
506.     listenersRef.current.forEach((listener) => listener());
507.   }, []);
508. 
509.   useEffect(() => {
510.     const unsubscribes = forms
511.       .map((form) => getStore(form.key)?.sub(responsesAtom, notify))
512.       .filter((unsub): unsub is () => void => !!unsub);
513.     return () => unsubscribes.forEach((unsub) => unsub());
514.   }, [forms, getStore, storesVersion, notify]);
515. 
516.   // Test bridge (Playwright drivability) — see `windowTestBridge.ts`'s own
517.   // doc comment for the gate. Registers/unregisters this exact handle
518.   // instance for the lifetime of the mount; a second concurrently mounted
519.   // session registers its OWN entry under its OWN random id, so both are
520.   // independently reachable via `window.__CARE_FILL_ASSISTANT__.list()`.
521.   useEffect(() => registerTestBridgeSession(handleRef.current!), []);
522. 
523.   return handleRef.current;
524. }
