86.     {
87.       url: `/api/v1/patient/${patientId}/`,
88.       method: "PUT" as const,
89.       body: { deceased_datetime: row.deceased_datetime },
90.       reference_id: structuredReferenceId("time_of_death", questionId),
91.     },
92.   ];
