70.   Record<QuestionType, ReadonlyArray<ResponseValue["type"]>>
71. > = {
72.   boolean: ["boolean"],
73.   decimal: ["number"],
74.   integer: ["number"],
75.   date: ["date"],
76.   dateTime: ["dateTime"],
77.   time: ["time"],
78.   string: ["string"],
79.   text: ["string"],
80.   url: ["string"],
81.   choice: ["string"],
82.   quantity: ["quantity"],
