98.  * matches a currently-available option. Only verifiable for a FIXED
99.  * option list known at merge time from the live `Question`
100.  * (`answer_option` for choice, `unit` for quantity): an
101.  * `answer_value_set`-backed question's real option set lives in a remote
102.  * valueset this pure, synchronous merge cannot expand — those restore
103.  * as-is (trusted, not verified).
104.  */
105. function choiceValueStillAvailable(
106.   question: Question,
107.   entry: ResponseValue,
108. ): boolean {
109.   if (!question.answer_option?.length) return true;
110.   const stored = entry.value == null ? undefined : String(entry.value);
111.   return question.answer_option.some((option) => option.value === stored);
112. }
