132.   question: Question,
133.   values: ResponseValue[],
134. ): { kept: ResponseValue[]; anyDropped: boolean } {
135.   if (question.type === "choice") {
136.     const kept = values.filter((entry) =>
137.       choiceValueStillAvailable(question, entry),
138.     );
139.     return { kept, anyDropped: kept.length !== values.length };
140.   }
141.   if (question.type === "quantity") {
142.     const kept = values.filter((entry) =>
143.       quantityUnitStillAvailable(question, entry),
144.     );
145.     return { kept, anyDropped: kept.length !== values.length };
146.   }
147.   return { kept: values, anyDropped: false };
148. }
