206. export function mergeDraftResponses(
207.   questions: Question[],
208.   draft: Record<string, QuestionnaireResponse>,
209. ): DraftMergeResult {
210.   const byId = indexQuestions(questions);
211.   const merged = initializeResponses(questions);
212.   const dropped: DroppedDraftAnswer[] = [];
213. 
214.   for (const [id, response] of Object.entries(draft)) {
215.     const fresh = byId.get(id);
216. 
217.     if (!fresh) {
218.       if (draftResponseHasContent(response)) {
219.         dropped.push({
220.           questionId: id,
221.           label: response.link_id || id,
222.           reason: "question_removed",
223.         });
224.       }
225.       continue;
226.     }
227. 
