43.   for (const key of Object.keys(localStorage)) {
44.     if (!key.startsWith(FILL_DRAFT_PREFIX)) continue;
45.     const userId = key.slice(FILL_DRAFT_PREFIX.length).split("--")[0];
46.     if (!userId || userId !== currentUserId) {
47.       localStorage.removeItem(key);
48.     }
49.   }
50. }
51. 
52. /** Drop expired/corrupt drafts (any user) — run on fill page mount and at
53.  *  provider boot, independent of auth outcome. */
54. export function sweepExpiredFillDrafts(): void {
55.   for (const key of Object.keys(localStorage)) {
56.     if (!key.startsWith(FILL_DRAFT_PREFIX)) continue;
57.     try {
58.       const draft = JSON.parse(localStorage.getItem(key) ?? "") as {
59.         savedAt?: string;
60.       };
61.       if (!draft.savedAt || isFillDraftExpired(draft.savedAt)) {
62.         localStorage.removeItem(key);
63.       }
64.     } catch {
65.       localStorage.removeItem(key);
66.     }
67.   }
68. }
