1. import { entryHasContent } from "@/components/QuestionnaireV2/form/engine/store";
2. import { resolveStructuredType } from "@/components/QuestionnaireV2/structured/registry";
3. 
4. import type { QuestionnaireResponse } from "@/types/questionnaire/form";
5. import type { Question } from "@/types/questionnaire/question";
6. import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
7. 
8. import type { DroppedDraftAnswer } from "./draftMerge";
9. import { draftResponseHasContent, mergeDraftResponses } from "./draftMerge";
10. import { FILL_DRAFT_PREFIX, isFillDraftExpired } from "./fillDraftCache";
11. 
12. /**
13.  * Local fill drafts — the crash/reload safety net. Draft data lives in
14.  * localStorage only under this prefix, scoped per user + subject + entry
15.  * questionnaire, TTL-bounded, and swept on an OTHER user's login, on
16.  * signOut and on app update — every eviction hook is deliberate; a new
17.  * session boundary must join the sweep list. Expired drafts are swept at
18.  * boot regardless of auth outcome. A user's OWN drafts deliberately
19.  * survive their own re-login — that is the crash/session-expiry recovery
20.  * this layer exists for, not a bug (see `fillDraftCache.ts`).
21.  *
22.  * One key holds the WHOLE fill session: the route-mounted questionnaire
23.  * plus every questionnaire added to the same submission.
24.  */
25. const SCHEMA_VERSION = 2;
26. 
27. export interface FillDraftScope {
28.   userId: string;
29.   /** encounterId when encounter-bound, else patientId. */
30.   subjectKey: string;
31.   /** The route-mounted questionnaire's id — the session key. */
32.   entryQuestionnaireId: string;
33. }
34. 
35. export interface DraftFormSnapshot {
36.   questionnaireId: string;
37.   /** `QuestionnaireRead.version` — a version bump invalidates this form
38.    *  (the read spec exposes no modified_date yet). */
39.   questionnaireVersion: string;
40.   /** The questionnaire's title as it read when the draft was written —
41.    *  the only human name available when a resume can no longer FETCH the
42.    *  questionnaire. Optional because v2 drafts written before this field
43.    *  existed are still valid; every reader must fall back. */
44.   title?: string;
45.   responses: Record<string, QuestionnaireResponse>;
46.   structuredSkipped: boolean;
47. }
48. 
49. interface StoredFillDraft {
50.   schemaVersion: number;
51.   savedAt: string;
52.   userId: string;
53.   subjectKey: string;
54.   entryQuestionnaireId: string;
55.   forms: DraftFormSnapshot[];
56. }
57. 
58. export interface LoadedFillDraft {
59.   forms: DraftFormSnapshot[];
60.   savedAt: string;
61.   /** True when the saved session had structured answers the draft could
62.    *  not carry (draftPolicy "exclude") — the restore bar says so. */
63.   structuredSkipped: boolean;
64.   /**
65.    * The restore bar's drop notice, precomputed for the PRIMARY form at
66.    * LOAD time (before the clinician even decides Resume vs Discard) —
67.    * `mergeDraftResponses` run against the questionnaire's CURRENT
68.    * questions. Empty when nothing would be lost, including the ordinary
69.    * case where the questionnaire never changed at all. Non-primary
70.    * (added) forms are merged later, when the host re-fetches them on
71.    * resume (`useFillSessionForms.ts`), and are not represented here.
72.    */
73.   dropped: DroppedDraftAnswer[];
74. }
75. 
76. function draftKey(scope: FillDraftScope): string {
77.   return `${FILL_DRAFT_PREFIX}${scope.userId}--${scope.subjectKey}--${scope.entryQuestionnaireId}`;
78. }
79. 
80. /**
81.  * One response as a draft stores it.
82.  *
83.  * A resolved structured question keeps its EDIT LOG and drops its
84.  * PROJECTION: those rows are the query layer's copy of the server's
85.  * data — restoring stale clinical rows and re-upserting them could
86.  * clobber edits made elsewhere. Edits are small, JSON-safe and meaningful
87.  * without the baseline (each carries its whole row), so a restore
88.  * re-fetches the rows and re-projects the log on top.
89.  *
90.  * Everything else — plain answers, an unresolvable structured type — is
91.  * stored verbatim (same object reference): this function is a no-op for
92.  * every response that isn't a resolved structured question.
93.  */
94. export function draftResponseForStorage(
95.   response: QuestionnaireResponse,
96. ): QuestionnaireResponse {
97.   if (!response.structured_type) return response;
98.   const resolved = resolveStructuredType(response.structured_type);
99.   if (!resolved) return response;
100.   return { ...response, values: [] };
101. }
102. 
103. /** Is this response one the draft deliberately leaves behind? An
104.  *  unresolvable structured type (its plugin isn't loaded) counts as
105.  *  "exclude": nothing here knows whether its values are serializable, and
106.  *  a restore would hand them to a component that may never come back.
107.  *  `files` is the only legitimate "exclude" among resolvable types (raw
108.  *  `File` objects cannot round-trip through JSON). */
109. function isDraftExcluded(response: QuestionnaireResponse): boolean {
110.   if (!response.structured_type) return false;
111.   const resolved = resolveStructuredType(response.structured_type);
112.   return !resolved || resolved.draftPolicy === "exclude";
113. }
114. 
115. /**
116.  * Split responses into draft-safe entries and skipped structured content.
117.  * `isDraftExcluded` responses never enter the draft — restoring stale
118.  * clinical rows and re-upserting them could clobber edits made elsewhere.
119.  * A "safe" entry still goes through `draftResponseForStorage`, which
120.  * strips a resolved structured question's projection down to its edit
121.  * log before it is stored.
122.  */
123. function partitionForDraft(responses: Record<string, QuestionnaireResponse>): {
124.   safe: Record<string, QuestionnaireResponse>;
125.   structuredSkipped: boolean;
126. } {
127.   const safe: Record<string, QuestionnaireResponse> = {};
128.   let structuredSkipped = false;
129.   for (const [id, response] of Object.entries(responses)) {
130.     if (isDraftExcluded(response)) {
131.       if (response.values.some(entryHasContent)) structuredSkipped = true;
132.       continue;
133.     }
134.     safe[id] = draftResponseForStorage(response);
135.   }
136.   return { safe, structuredSkipped };
137. }
138. 
139. /**
140.  * Overlay the draft-excluded structured entries a store already holds onto
141.  * a record that is about to REPLACE it.
142.  *
143.  * Resume and Discard both swap a form's whole responses record. Structured
144.  * types with `draftPolicy: "exclude"` are by definition not in the draft,
145.  * and the adapted widgets seed them once from a server prefetch in a mount
146.  * effect that never re-runs — so a plain replacement blanks the patient's
147.  * existing allergies/medications/diagnoses on screen, and re-entering them
148.  * upserts DUPLICATE clinical records. The live values are the only copy;
149.  * they carry across untouched.
150.  */
151. export function preserveExcludedStructured(
152.   current: Record<string, QuestionnaireResponse>,
153.   next: Record<string, QuestionnaireResponse>,
154. ): Record<string, QuestionnaireResponse> {
155.   const merged = { ...next };
156.   for (const [id, response] of Object.entries(current)) {
157.     if (!isDraftExcluded(response)) continue;
158.     const fresh = merged[id];
159.     // Same guard the draft overlay uses: only where the question still
160.     // exists with the same structured_type.
161.     if (fresh && fresh.structured_type === response.structured_type) {
162.       merged[id] = response;
163.     }
164.   }
165.   return merged;
166. }
167. 
168. /**
169.  * The creation-time merge rule for resume paths: draft entries overlay
170.  * the fresh seed per `draftMerge.ts`'s compatibility rules — restoring
171.  * where the question still exists with a shape-compatible type/option,
172.  * dropping what does not. A thin wrapper for call sites that don't
173.  * surface the drop list (`useFillAutosave.ts`'s primary-form resume,
174.  * whose drops `loadFillDraft` already precomputed at detection time, and
175.  * `useFillSessionForms.ts`'s added-form paths).
176.  */
177. export function mergeDraftIntoSeed(
178.   questions: Question[],
179.   draft: Record<string, QuestionnaireResponse>,
180. ): Record<string, QuestionnaireResponse> {
181.   return mergeDraftResponses(questions, draft).responses;
182. }
183. 
184. /** The live working state of one form, as the fill host reads it out of
185.  *  that form's store. */
186. export interface FillSessionFormState {
187.   questionnaire: QuestionnaireRead;
188.   responses: Record<string, QuestionnaireResponse>;
189. }
190. 
191. function snapshotSession(forms: FillSessionFormState[]): {
192.   snapshots: DraftFormSnapshot[];
193.   anyContent: boolean;
194. } {
195.   const snapshots: DraftFormSnapshot[] = [];
196.   let anyContent = false;
197.   for (const form of forms) {
198.     const { safe, structuredSkipped } = partitionForDraft(form.responses);
