261.   const carried = retained.filter(
262.     (snapshot) => !live.has(snapshot.questionnaireId),
263.   );
264.   const carriedContent = carried.some((snapshot) =>
265.     Object.values(snapshot.responses).some(draftResponseHasContent),
266.   );
