287.  *  Date objects so the inputs' discriminant checks keep working. Exported
288.  *  for the server-draft (`?continue_draft=`) restore path, whose dump went
289.  *  through the same JSON flattening. */
290. export function reviveDraftResponses(
291.   responses: Record<string, QuestionnaireResponse>,
292. ): Record<string, QuestionnaireResponse> {
293.   for (const response of Object.values(responses)) {
294.     // Server dumps are untyped blobs — a `values`-less entry is possible
295.     // and must not throw the whole encounter overview.
