343.       draft.schemaVersion !== SCHEMA_VERSION ||
344.       draft.userId !== scope.userId ||
345.       draft.subjectKey !== scope.subjectKey ||
346.       draft.entryQuestionnaireId !== scope.entryQuestionnaireId ||
347.       isFillDraftExpired(draft.savedAt) ||
