358.       forms: draft.forms,
359.       savedAt: draft.savedAt,
360.       structuredSkipped: draft.forms.some((form) => form.structuredSkipped),
361.       dropped,
362.     };
363.   } catch {
364.     localStorage.removeItem(key);
365.     return undefined;
366.   }
367. }
