     schemaVersion: SCHEMA_VERSION,
     savedAt: new Date().toISOString(),
     userId: scope.userId,
     subjectKey: scope.subjectKey,
     entryQuestionnaireId: scope.entryQuestionnaireId,
     forms: [...snapshots, ...carried],
   };
