         (entry.type === "date" || entry.type === "dateTime") &&
         typeof raw === "string"
       ) {
         const revived = new Date(raw);
         entry.value = isNaN(revived.getTime()) ? undefined : revived;
       }
     }
   }
   return responses;
 }

