26. import { collectStructuredErrors } from "./validateStructured";
27. 
28. /**
29.  * The backend's `/api/v1/batch_requests/` endpoint hard-caps the number of
30.  * sub-requests per call (`MAX_REQUESTS_PER_BATCH_REQUEST` in the care
31.  * backend settings) and 400s the WHOLE batch past it — a generic error the
32.  * clinician would only see after filling in every question. Checked here so
33.  * the abort is specific and costs no network round trip.
34.  */
35. const MAX_BATCH_REQUESTS = 20;
36. 
37. interface UseSubmitFillSessionArgs {
38.   /** Every questionnaire in the session, primary first. */
39.   forms: FillFormEntry[];
40.   getStore: (key: string) => FormStore | undefined;
41.   subject: FillSubject;
42.   continueDraftId?: string;
43.   /** Titles of drafted forms the session is currently carrying WITHOUT a
44.    *  live store — a resume whose re-fetch of an added questionnaire
45.    *  failed and is still retained in the draft (see
46.    *  `QuestionnaireFillPage`'s `retainedSnapshots`). Submitting anyway
47.    *  would clear the draft in `onSuccess` and take those answers with it,
48.    *  having never been in the batch. */
49.   blockedFormLabels: string[];
50.   onSuccess: () => void;
51. }
52. 
53. /**
54.  * Reveal the first failing question — every block carries the
55.  * `data-question-id` anchor and every input the `question-input-{id}` one.
56.  * Deferred a tick so the error render exists before we measure (same
57.  * reason legacy used setTimeout).
58.  *
59.  * Focus moves as well as the scroll: a `scrollIntoView` alone leaves a
60.  * keyboard or screen-reader user parked on the Save button with no way to
61.  * find what failed. Where the question has no focusable input of its own
62.  * (structured sections, unsupported types) the block itself takes focus
63.  * through a programmatic-only tabindex, so the error text right below it
64.  * is what gets read.
65.  */
66. function scrollToQuestion(questionId: string) {
67.   setTimeout(() => {
68.     const block = document.querySelector<HTMLElement>(
69.       `[data-question-id="${questionId}"]`,
70.     );
71.     if (!block) return;
72.     block.scrollIntoView({
73.       block: "center",
74.       behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
75.         ? "auto"
76.         : "smooth",
77.     });
78.     const input = document.getElementById(`question-input-${questionId}`);
79.     if (input) {
80.       input.focus({ preventScroll: true });
81.       return;
82.     }
83.     block.setAttribute("tabindex", "-1");
84.     block.focus({ preventScroll: true });
85.   });
86. }
87. 
88. /** `error.cause` off the wire is untyped — accept it as a batch failure
89.  *  payload only when it structurally carries a `results` array. */
90. function hasBatchResults(
91.   cause: unknown,
92. ): cause is { results: Parameters<typeof mapBatchErrors>[0] } {
93.   return (
94.     typeof cause === "object" &&
95.     cause !== null &&
96.     Array.isArray((cause as { results?: unknown }).results)
97.   );
98. }
99. 
100. /** `questionId → formKey` across the whole session, so a batch failure
101.  *  lands in the store of the form that owns the question. */
102. function buildQuestionOwnerIndex(forms: FillFormEntry[]): Map<string, string> {
103.   const questionToForm = new Map<string, string>();
104.   for (const form of forms) {
105.     const walk = (questions: Question[]) => {
106.       for (const question of questions) {
107.         questionToForm.set(question.id, form.key);
108.         if (question.questions) walk(question.questions);
109.       }
110.     };
111.     walk(form.questionnaire.questions);
112.   }
113.   return questionToForm;
114. }
115. 
116. /**
117.  * The fill host's submit action — the errorsAtom writer the engine
118.  * documented since the fill seams landed. Lives outside the form
119.  * providers and reaches each form's instance store through the host's
120.  * registry, so one click submits the whole session.
121.  *
122.  * Flow: client validation (required + structured registry validators)
123.  * runs per form, writes failures into that form's `errorsAtom` and aborts
124.  * with a scroll to the first one; otherwise every form composes its
125.  * requests into ONE batch (legacy semantics — the added questionnaires
126.  * ride along with the primary), and failures map back per reference_id
127.  * into the owning form's `errorsAtom` plus the page-level panel.
128.  */
129. export function useSubmitFillSession({
130.   forms,
131.   getStore,
132.   subject,
133.   continueDraftId,
134.   blockedFormLabels,
135.   onSuccess,
136. }: UseSubmitFillSessionArgs) {
137.   const { t } = useTranslation();
138.   const [serverErrors, setServerErrors] = useState<ServerValidationError[]>([]);
139. 
140.   const { mutate: submitBatch, isPending } = useMutation({
141.     // Silent: batch failures are handled here (panel + per-question), not
142.     // by the global error toast.
143.     // TODO: migrate to useBatchRequest once it can take pre-built batch
144.     // entries (these requests carry raw urls) and can opt out of the
145.     // global error toast — same blocker the legacy form recorded.
146.     // eslint-disable-next-line @typescript-eslint/no-deprecated
147.     mutationFn: mutate(batchApi.batchRequest, { silent: true }),
148.     onSuccess: () => {
149.       setServerErrors([]);
150.       toast.success(t("questionnaire_submitted_successfully"));
151.       onSuccess();
152.     },
153.     onError: (error) => {
154.       if (hasBatchResults(error.cause)) {
155.         const mapped = mapBatchErrors(
156.           error.cause.results,
157.           t("validation_failed"),
158.         );
159.         setServerErrors(mapped.serverErrors);
160. 
161.         // Route each question failure to the form that owns it — the
162.         // batch is flat, the stores are not.
163.         const questionToForm = buildQuestionOwnerIndex(forms);
164.         const byForm = new Map<string, QuestionValidationError[]>();
165.         for (const questionError of mapped.questionErrors) {
166.           const formKey = questionToForm.get(questionError.question_id);
167.           if (!formKey) continue;
168.           byForm.set(formKey, [...(byForm.get(formKey) ?? []), questionError]);
169.         }
170.         for (const form of forms) {
171.           getStore(form.key)?.set(errorsAtom, byForm.get(form.key) ?? []);
172.         }
173.         if (mapped.questionErrors.length > 0) {
174.           scrollToQuestion(mapped.questionErrors[0].question_id);
175.         }
176.       }
177.       toast.error(t("questionnaire_submission_failed"));
178.     },
179.   });
180. 
181.   const runSubmit = useCallback(async () => {
182.     // 0) Every session form must have a live store to read responses from,
183.     //    and nothing may be sitting in the draft as a retained-but-
184.     //    unmounted snapshot (`blockedFormLabels` — a resume whose re-fetch
185.     //    of an added questionnaire failed). Either condition means this
186.     //    batch would silently omit that form's answers — the validation
187.     //    loop and compose below just `continue`/skip a missing store with
188.     //    no signal — and a successful submit's `onSuccess` clears the
189.     //    WHOLE draft, retained snapshots included, even though they were
190.     //    never in the batch. Abort before validation even runs.
191.     const missingStoreForms = forms.filter((form) => !getStore(form.key));
192.     if (missingStoreForms.length > 0 || blockedFormLabels.length > 0) {
193.       const names = [
194.         ...missingStoreForms.map((form) => form.questionnaire.title),
195.         ...blockedFormLabels,
196.       ];
197.       toast.error(
198.         t("questionnaire_submit_missing_forms", { forms: names.join(", ") }),
199.       );
200.       return;
201.     }
202. 
203.     // 1) Validate every form against its own store; the first failure
204.     //    anywhere in the session decides where we scroll. The renderer's
205.     //    flat subject view and the form's render-failed set go in so the
206.     //    required check can tell a structured question that HAS an input
207.     //    from one showing a notice (see form/validation.ts).
208.     const rendererSubject = rendererSubjectOf(subject);
209.     let firstError: { formKey: string; questionId: string } | undefined;
210.     for (const form of forms) {
211.       const store = getStore(form.key);
212.       if (!store) continue;
213.       const responses = store.get(responsesAtom);
214.       const renderFailed = store.get(structuredRenderFailedAtom);
215.       const clientErrors: QuestionValidationError[] = [
216.         ...collectRequiredErrors(form.questionnaire.questions, responses, t, {
217.           questionnaire: form.questionnaire,
218.           subject: rendererSubject,
219.           renderFailed,
220.         }),
221.         ...collectStructuredErrors(
222.           form.questionnaire,
223.           responses,
224.           rendererSubject,
225.           renderFailed,
226.           t,
227.         ),
228.       ];
229.       store.set(errorsAtom, clientErrors);
230.       if (clientErrors.length > 0 && !firstError) {
231.         // "First" in the clinician's reading order, not in validator
232.         // order — the array concatenates every required failure before
233.         // any structured one, so its head can sit far below an earlier
234.         // failing question on screen.
235.         const failing = new Set(clientErrors.map((error) => error.question_id));
236.         const inTreeOrder = (questions: Question[]): string | undefined => {
237.           for (const question of questions) {
238.             if (failing.has(question.id)) return question.id;
239.             const found = inTreeOrder(question.questions ?? []);
240.             if (found) return found;
241.           }
242.           return undefined;
243.         };
244.         firstError = {
245.           formKey: form.key,
246.           questionId:
247.             inTreeOrder(form.questionnaire.questions) ??
248.             clientErrors[0].question_id,
249.         };
250.       }
251.     }
252.     if (firstError) {
253.       // The per-question messages are `role="alert"` and focus lands on
254.       // the first failure, but the abort itself needs saying out loud too:
255.       // without it a screen-reader user who pressed Save Changes gets no
256.       // signal that the submission was rejected at all.
257.       toast.error(t("validation_failed"));
258.       scrollToQuestion(firstError.questionId);
259.       return;
260.     }
261.     setServerErrors([]);
262. 
263.     // 2) One batch across all forms (composeBatch already orders
264.     //    structured requests first WITHIN a form). Only the primary form
265.     //    carries the resumed server draft's completion PUT.
266.     let requests: Awaited<ReturnType<typeof composeBatch>>;
267.     try {
268.       requests = (
269.         await Promise.all(
270.           forms.map((form) => {
271.             const store = getStore(form.key);
272.             if (!store) return Promise.resolve([]);
273.             return composeBatch({
274.               questionnaire: form.questionnaire,
275.               responses: store.get(responsesAtom),
276.               subject,
277.               renderFailed: store.get(structuredRenderFailedAtom),
278.               continueDraftId: form.isPrimary ? continueDraftId : undefined,
279.             });
280.           }),
281.         )
282.       ).flat();
283.     } catch (error) {
284.       // A structured type's `buildRequests` threw. Pin it to the question
285.       // that produced it in that question's own store, and fail the way
286.       // every other submission failure fails — never as a silent no-op.
287.       if (!(error instanceof StructuredBuildError)) throw error;
288.       const formKey = buildQuestionOwnerIndex(forms).get(error.questionId);
289.       for (const form of forms) {
290.         getStore(form.key)?.set(
291.           errorsAtom,
292.           form.key === formKey
293.             ? [
294.                 {
295.                   question_id: error.questionId,
296.                   error: t("structured_question_submit_failed"),
297.                 },
298.               ]
299.             : [],
300.         );
301.       }
302.       toast.error(t("questionnaire_submission_failed"));
303.       scrollToQuestion(error.questionId);
304.       return;
305.     }
306.     if (requests.length === 0) {
307.       toast.error(t("no_answers_to_submit"));
308.       return;
309.     }
310.     // The backend rejects the whole batch past this — see
311.     // `MAX_BATCH_REQUESTS`. Caught here, before any network call, so the
312.     // clinician learns exactly what to trim instead of reading a generic
313.     // 400 after everything was already typed in.
314.     if (requests.length > MAX_BATCH_REQUESTS) {
315.       toast.error(
316.         t("questionnaire_batch_too_large", {
317.           count: requests.length,
318.           max: MAX_BATCH_REQUESTS,
319.         }),
320.       );
321.       return;
322.     }
323.     submitBatch({ requests });
324.   }, [
325.     forms,
326.     getStore,
327.     subject,
328.     continueDraftId,
329.     blockedFormLabels,
330.     submitBatch,
331.     t,
332.   ]);
333. 
334.   // Compose runs BEFORE the mutation starts, and structured
335.   // `buildRequests` are async — during that window the mutation's
336.   // isPending is still false, so a second click would validate and
337.   // compose a second identical batch. The ref closes the window
338.   // synchronously (state alone leaves the same-tick gap); the state twin
339.   // keeps the button disabled for the same span.
340.   const composingRef = useRef(false);
341.   const [isComposing, setIsComposing] = useState(false);
342. 
343.   /**
344.    * The one entry point, and the outermost containment boundary. The page
345.    * fires this as `onSubmit={() => void submit()}`, so ANY escaping
346.    * rejection — a plugin component's getter, a malformed store record, a
347.    * future call added inside `runSubmit` — would become an unhandled
348.    * promise rejection and turn Save Changes into a silent no-op. Failing
349.    * loudly is the floor: the clinician always learns the submission did
350.    * not happen, and the original error still reaches the console for the
351.    * developer.
352.    */
353.   const submit = useCallback(async () => {
354.     if (composingRef.current || isPending) return;
355.     composingRef.current = true;
356.     setIsComposing(true);
357.     try {
358.       await runSubmit();
359.     } catch (error) {
360.       console.error("Questionnaire submission failed unexpectedly", error);
361.       toast.error(t("questionnaire_submission_failed"));
362.     } finally {
363.       composingRef.current = false;
364.       setIsComposing(false);
365.     }
366.   }, [runSubmit, isPending, t]);
367. 
368.   return {
369.     submit,
370.     isPending: isPending || isComposing,
371.     // Exposed separately (rather than only folded into `isPending` above)
372.     // so a consumer that needs the tri-state distinction — composing the
373.     // batch vs. the request actually in flight — can derive it without
374.     // reaching into this hook's internals. Nothing here changes: the
375.     // combined `isPending` a caller was already reading is untouched.
376.     isComposing,
377.     serverErrors,
378.   };
379. }
380.

