1. import { useQuery } from "@tanstack/react-query";
2. import { ArrowLeft, Plus } from "lucide-react";
3. import { navigate, useQueryParams } from "raviger";
4. import { useEffect, useMemo } from "react";
5. import { useTranslation } from "react-i18next";
6. 
7. import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
8. import { Button } from "@/components/ui/button";
9. 
10. import { FormSkeleton } from "@/components/Common/SkeletonLoading";
11. import { QuestionnaireSearch } from "@/components/Questionnaire/QuestionnaireSearch";
12. import { FIXED_QUESTIONNAIRES } from "@/components/Questionnaire/data/StructuredFormData";
13. 
14. import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";
15. 
16. import useAuthUser from "@/hooks/useAuthUser";
17. 
18. import query from "@/Utils/request/query";
19. import encounterApi from "@/types/emr/encounter/encounterApi";
20. import patientApi from "@/types/emr/patient/patientApi";
21. import type { QuestionnaireResponse } from "@/types/questionnaire/form";
22. import type { FormSubmissionRead } from "@/types/questionnaire/formSubmission";
23. import formSubmissionApi from "@/types/questionnaire/formSubmissionApi";
24. import type {
25.   QuestionnaireRead,
26.   SubjectType,
27. } from "@/types/questionnaire/questionnaire";
28. import questionnaireApi from "@/types/questionnaire/questionnaireApi";
29. 
30. import { FillPageBody } from "./FillPageBody";
31. import { FillShell } from "./FillShell";
32. import { sweepExpiredFillDrafts } from "./draft/fillDraftCache";
33. import type { FillDraftScope, LoadedFillDraft } from "./draft/fillDraftStore";
34. import { loadFillDraft, reviveDraftResponses } from "./draft/fillDraftStore";
35. import type { FillSubject } from "./subject";
36. import { exitTargetOf, isPatientBound, subjectKeyOf } from "./subject";
37. 
38. interface FillPageProps {
39.   /** What this fill is FOR — the union carries exactly the ids the
40.    *  mounting route can supply (see `fill/subject.ts`). */
41.   subject: FillSubject;
42.   questionnaireId?: string;
43.   /** What the questionnaire pickers filter on, when that differs from the
44.    *  subject's own type. Only the encounter-CREATION mount needs it: its
45.    *  subject is the patient (no encounter exists yet), but the forms it
46.    *  offers alongside are the encounter's. Defaults to `subject.type`. */
47.   pickerSubjectType?: SubjectType;
48. }
49. 
50. type ServerDraftState =
51.   | { mismatch: true }
52.   | { mismatch: false; responses: Record<string, QuestionnaireResponse> };
53. 
54. function isRecord(value: unknown): value is Record<string, unknown> {
55.   return typeof value === "object" && value !== null;
56. }
57. 
58. /**
59.  * Validate and extract a resumed server draft's responses. The embedded
60.  * questionnaire id must match the live one — the legacy recoverability
61.  * guard. `response_dump` is a free-form JSON blob the server never
62.  * validates, so its shape is checked at runtime instead of trusted with a
63.  * cast: a malformed dump lands on the "draft not recoverable" branch here
64.  * rather than surfacing as crashes deep in the renderer.
65.  */
66. function parseServerDraft(
67.   serverDraft: FormSubmissionRead,
68.   questionnaire: QuestionnaireRead,
69. ): ServerDraftState {
70.   // Only an open draft resumes. A record already submitted (or marked
71.   // entered-in-error) re-opening as editable would let one submission
72.   // file twice — the overview's drafts card filters these out, but the
73.   // URL is shareable and outlives that filter.
74.   if (serverDraft.status !== "draft") {
75.     return { mismatch: true };
76.   }
77.   const dump: unknown = serverDraft.response_dump;
78.   const form = isRecord(dump) ? dump.questionnaireResponses : undefined;
79.   if (
80.     !isRecord(form) ||
81.     !isRecord(form.questionnaire) ||
82.     form.questionnaire.id !== questionnaire.id ||
83.     !Array.isArray(form.responses)
84.   ) {
85.     return { mismatch: true };
86.   }
87.   const record: Record<string, QuestionnaireResponse> = {};
88.   for (const item of form.responses as unknown[]) {
89.     if (!isRecord(item) || typeof item.question_id !== "string") {
90.       return { mismatch: true };
91.     }
92.     // Beyond `question_id` the entry is trusted as a QuestionnaireResponse
93.     // this page's own save path wrote; `reviveDraftResponses` defends the
94.     // date fields it touches.
95.     record[item.question_id] = item as unknown as QuestionnaireResponse;
96.   }
97.   return { mismatch: false, responses: reviveDraftResponses(record) };
98. }
99. 
100. /**
101.  * The v2 fill experience — the questionnaire data-entry page (successor to
102.  * EncounterQuestionnaire + the legacy QuestionnaireForm). Patient-bound
103.  * subjects get two tabs per the reference: the questionnaire canvas (with
104.  * local autosave) and the patient's clinical history; resource subjects
105.  * (location/device/facility) get the canvas alone, since none of the
106.  * clinical context exists for them.
107.  *
108.  * A session may hold SEVERAL questionnaires (the legacy "add another form
109.  * to this submission" capability): each gets its own provider and store,
110.  * the host keeps the registry, and autosave/submit operate on the list.
111.  *
112.  * This component is the gatekeeper: queries, draft loading and every
113.  * refuse-to-mount branch. The loaded session itself is `FillPageBody`.
114.  */
115. export default function QuestionnaireFillPage({
116.   subject,
117.   questionnaireId,
118.   pickerSubjectType = subject.type,
119. }: FillPageProps) {
120.   const { t } = useTranslation();
121.   const [{ continue_draft: continueDraftParam }] = useQueryParams();
122.   const user = useAuthUser();
123. 
124.   const patientBound = isPatientBound(subject) ? subject : undefined;
125.   // Server drafts are patient/encounter records — a resource subject can
126.   // only have local drafts, so the query param is ignored there.
127.   const continueDraftId = patientBound ? continueDraftParam : undefined;
128. 
129.   useEffect(() => {
130.     sweepExpiredFillDrafts();
131.   }, []);
132. 
133.   const fixedQuestionnaire = questionnaireId
134.     ? FIXED_QUESTIONNAIRES[questionnaireId]
135.     : undefined;
136. 
137.   const {
138.     data: fetchedQuestionnaire,
139.     isLoading: isQuestionnaireLoading,
140.     isError: isQuestionnaireError,
141.   } = useQuery({
142.     queryKey: questionnaireKeys.detail(questionnaireId ?? ""),
143.     queryFn: query(questionnaireApi.get, {
144.       pathParams: { id: questionnaireId ?? "" },
145.     }),
146.     enabled: !!questionnaireId && !fixedQuestionnaire,
147.   });
148. 
149.   const encounterId =
150.     subject.type === "encounter" ? subject.encounterId : undefined;
151.   const {
152.     data: encounter,
153.     isLoading: isEncounterLoading,
154.     isError: isEncounterError,
155.   } = useQuery({
156.     queryKey: ["encounter", encounterId],
157.     queryFn: query(encounterApi.get, {
158.       pathParams: { id: encounterId ?? "" },
159.       queryParams: {
160.         facility: subject.type === "encounter" ? subject.facilityId : "",
161.       },
162.     }),
163.     enabled: !!encounterId,
164.   });
165. 
166.   // Patient-subject fills have no encounter to borrow the patient from;
167.   // resource subjects have no patient at all.
168.   const { data: fetchedPatient, isError: isPatientError } = useQuery({
169.     queryKey: ["patient", patientBound?.patientId],
170.     queryFn: query(patientApi.get, {
171.       pathParams: { id: patientBound?.patientId ?? "" },
172.     }),
173.     enabled: subject.type === "patient",
174.   });
175. 
176.   const {
177.     data: serverDraft,
178.     // isLoading, NOT isFetching: a background refetch (window focus, cache
179.     // invalidation) flips isFetching while data is still present, and the
180.     // skeleton branch below would unmount the whole session — every form
181.     // store and every answer typed since resume — mid-edit.
182.     isLoading: isServerDraftLoading,
183.     isError: isServerDraftError,
184.   } = useQuery({
185.     queryKey: ["formSubmission", continueDraftId],
186.     queryFn: query(formSubmissionApi.get, {
187.       pathParams: { external_id: continueDraftId ?? "" },
188.     }),
189.     enabled: !!continueDraftId,
190.   });
191. 
192.   const questionnaire = fixedQuestionnaire ?? fetchedQuestionnaire;
193.   const patient = encounter?.patient ?? fetchedPatient;
194. 
195.   // Server draft (continue_draft) supersedes any local draft.
196.   const serverDraftState = useMemo<ServerDraftState | undefined>(
197.     () =>
198.       continueDraftId && serverDraft && questionnaire
199.         ? parseServerDraft(serverDraft, questionnaire)
200.         : undefined,
201.     [continueDraftId, serverDraft, questionnaire],
202.   );
203. 
204.   const scope: FillDraftScope | undefined = questionnaire
205.     ? {
206.         userId: user.id,
207.         subjectKey: subjectKeyOf(subject),
208.         entryQuestionnaireId: questionnaire.id,
209.       }
210.     : undefined;
211. 
212.   // Loaded once per (user, subject, entry questionnaire) — reruns of this
213.   // memo after autosave writes don't happen because the deps are stable.
214.   // The primary form's version gates the whole session draft.
215.   const scopeKey = scope
216.     ? `${scope.userId}--${scope.subjectKey}--${scope.entryQuestionnaireId}`
217.     : undefined;
218.   const localDraft = useMemo<LoadedFillDraft | undefined>(
219.     () =>
220.       scopeKey && scope && questionnaire && !continueDraftId
221.         ? loadFillDraft(scope, questionnaire.questions)
222.         : undefined,
223.     // eslint-disable-next-line react-hooks/exhaustive-deps
224.     [scopeKey, continueDraftId],
225.   );
226. 
227.   const exitTarget = exitTargetOf(subject);
228. 
229.   if (!questionnaireId) {
230.     return (
231.       <FillShell onClose={() => navigate(exitTarget)}>
232.         <div className="flex flex-1 flex-col items-center justify-center gap-4 p-6 text-center">
233.           <h2 className="text-lg font-semibold text-gray-900">
234.             {t("select_questionnaire_to_fill")}
235.           </h2>
236.           {/* Default onSelect navigates to `questionnaire/{id}` relative to
237.               the current path, which lands on this mount's :questionnaireId
238.               route for every subject. The trigger is supplied rather than
239.               defaulted for the same reason the in-session picker's is: a
240.               `role="combobox"` takes no accessible name from its contents,
241.               so the only control on this screen would reach screen readers
242.               unnamed. The role stays (this IS the picker), the name comes
243.               from aria-label. */}
244.           <QuestionnaireSearch
245.             subjectType={pickerSubjectType}
246.             trigger={
247.               <Button
248.                 type="button"
249.                 variant="outline"
250.                 role="combobox"
251.                 aria-label={t("select_questionnaire_to_fill")}
252.                 className="w-full border border-primary-600 text-primary-800"
253.               >
254.                 <Plus className="size-4" />
255.                 {t("add_forms")}
256.               </Button>
257.             }
258.           />
259.         </div>
260.       </FillShell>
261.     );
262.   }
263. 
264.   if (
265.     isQuestionnaireLoading ||
266.     (encounterId && isEncounterLoading) ||
267.     (continueDraftId && isServerDraftLoading)
268.   ) {
269.     // Same fullscreen shell the loaded page uses, so the layout doesn't
270.     // jump shells when data lands — and the close affordance exists even
271.     // while loading.
272.     return (
273.       <FillShell onClose={() => navigate(exitTarget)}>
274.         <div className="min-h-0 flex-1 overflow-hidden px-6 py-4">
275.           <FormSkeleton rows={10} />
276.         </div>
277.       </FillShell>
278.     );
279.   }
280. 
281.   if (isQuestionnaireError || !questionnaire) {
282.     return (
283.       <FillErrorPage message={t("no_data_found")} exitTarget={exitTarget} />
284.     );
285.   }
286. 
287.   // The fetched questionnaire was authored for a subject family this mount
288.   // cannot supply (e.g. a location/device/facility questionnaire id pasted
289.   // into a patient route). Mounting anyway would let the clinician fill the
290.   // entire form before the backend rejects it at Save (400, atomic batch
291.   // rollback) with no clue why. Patient-bound mounts (patient + encounter
292.   // routes) share one family — a patient-subject questionnaire can be filled
293.   // from an encounter route and vice versa, same as the legacy
294.   // pre-encounter "consultation" route proves by mounting an
295.   // encounter-subject fixed questionnaire on a patient subject — so only
296.   // resource mounts (location/device/facility) require an exact match.
297.   const subjectTypeMismatch = patientBound
298.     ? questionnaire.subject_type !== "patient" &&
299.       questionnaire.subject_type !== "encounter"
300.     : questionnaire.subject_type !== subject.type;
301.   if (subjectTypeMismatch) {
302.     return (
303.       <FillErrorPage
304.         message={t("fill_subject_type_mismatch")}
305.         exitTarget={exitTarget}
306.       />
307.     );
308.   }
309. 
310.   // The clinical context could not be LOADED (the app's query default is
311.   // retry:false, so one blip lands here). Mounting the form anyway would
312.   // show a headerless page with no patient identity, blood group or
313.   // allergy badges — safety-relevant context — while the clinician types
314.   // clinical data into it.
315.   if ((encounterId && isEncounterError) || isPatientError) {
316.     return (
317.       <FillErrorPage
318.         message={t("fill_context_load_failed")}
319.         exitTarget={exitTarget}
320.       />
321.     );
322.   }
323. 
324.   // The draft record could not be READ (404, permissions, a network
325.   // hiccup — the app's query default is retry:false). Mounting the form
326.   // anyway would show a blank questionnaire with no explanation, invite a
327.   // full re-type into a page whose local autosave is deliberately off, and
328.   // then compose a completion PUT for a draft that was never loaded — one
329.   // failed sub-request rolls the whole atomic batch back, so the URL
330.   // becomes an un-submittable dead end. Legacy showed an error page here.
331.   if (isServerDraftError) {
332.     return (
333.       <FillErrorPage message={t("draft_load_failed")} exitTarget={exitTarget} />
334.     );
335.   }
336. 
337.   if (serverDraftState?.mismatch) {
338.     return (
339.       <FillErrorPage
340.         message={t("draft_not_recoverable")}
341.         exitTarget={exitTarget}
342.       />
343.     );
344.   }
345. 
346.   // The route's patientId and encounterId disagree on whose encounter this
347.   // is (a hand-edited or stale URL) — mounting would show patient B's
348.   // identity banner and clinical history beside patient A's structured
349.   // widget context. Only checked once the encounter query has actually
350.   // resolved (the loading/error branches above already accounted for
351.   // "still loading" and "failed to load").
352.   if (
353.     subject.type === "encounter" &&
354.     encounter &&
355.     encounter.patient.id !== subject.patientId
356.   ) {
357.     return (
358.       <FillErrorPage
359.         message={t("fill_patient_encounter_mismatch")}
360.         exitTarget={exitTarget}
361.       />
362.     );
363.   }
364. 
365.   return (
366.     <FillPageBody
367.       questionnaire={questionnaire}
368.       patient={patient}
369.       encounter={encounter}
370.       subject={subject}
371.       pickerSubjectType={pickerSubjectType}
372.       scope={scope}
373.       localDraft={localDraft}
374.       serverDraftResponses={
375.         serverDraftState && !serverDraftState.mismatch
376.           ? serverDraftState.responses
377.           : undefined
378.       }
379.       continueDraftId={continueDraftId}
380.       exitTarget={exitTarget}
381.     />
382.   );
383. }
384. 
385. /** The one dead-end state of this page: an alert plus the way back. Every
386.  *  branch that refuses to mount a form uses it, so "we could not open this"
387.  *  always reads the same and always announces (the ui Alert is
388.  *  role="alert"). */
389. function FillErrorPage({
390.   message,
391.   exitTarget,
392. }: {
393.   message: string;
394.   exitTarget: string;
395. }) {
396.   const { t } = useTranslation();
397.   return (
398.     <div className="space-y-4 p-6">
399.       <Alert variant="destructive">
400.         <AlertTitle>{t("error")}</AlertTitle>
401.         <AlertDescription>{message}</AlertDescription>
402.       </Alert>
403.       <Button variant="outline" onClick={() => navigate(exitTarget)}>
404.         <ArrowLeft className="size-4" />
405.         {t("back")}
406.       </Button>
407.     </div>
408.   );
409. }
410.

