python3 - <<'PY'
from pathlib import Path
import re
roots=[Path('src/components/QuestionnaireV2/structured/types'),Path('src/components/QuestionnaireV2/structured/definitions')]
terms=re.compile(r'(spec amendment|master plan|Batch [A-E]|Phase \d|carry-forward|task \d|later task|earlier task|\(item \d\)|annex|docs/superpowers|rearchitecture|old system|legacy stack|per the review|before .* existed|used to|ported from|mirrors the old|deleted with that stack|restored two dropped|P0|P1|\blegacy\b|\bport\b|Question\.tsx|\.spec|:[0-9]+(?:-[0-9]+)?|\bcommit\b|\breview\b|\bbrief\b|D\d)', re.I)
count=0
for root in roots:
  for p in sorted(root.rglob('*')):
    if p.suffix not in ('.ts','.tsx') or p.name.endswith('.test.ts'): continue
    lines=p.read_text().splitlines(); i=0; blocks=[]
    while i<len(lines):
      s=lines[i].strip()
      if s.startswith('//'):
        start=i+1; block=[]
        while i<len(lines) and lines[i].strip().startswith('//'):
          block.append(lines[i]); i+=1
        txt='\n'.join(block)
        if terms.search(txt): blocks.append((start,txt))
      elif s.startswith('/*'):
        start=i+1; block=[]
        while i<len(lines):
          block.append(lines[i])
          if '*/' in lines[i]: i+=1; break
          i+=1
        txt='\n'.join(block)
        if terms.search(txt): blocks.append((start,txt))
      else:
        i+=1
    if blocks:
      print(f'### {p}')
      for start,txt in blocks:
        count+=1
        print(f'-- line {start} --')
        print(txt)
print('TOTAL', count)
PY

